48	const toolResultStatusError = "error"
49	
50	// toolResultJSON is the compact result object inlined into tool_use blocks.
51	type toolResultJSON struct {
52		Output     string              `json:"output"`
53		Status     string              `json:"status"`
54		File       *toolResultFileJSON `json:"file,omitempty"`
55		MatchCount int                 `json:"matchCount,omitempty"`
56	}
