361	// mergeAssistantEntries combines two assistant entries with the same message ID.
362	// Content arrays are concatenated; the later timestamp and token counts win
363	// (streaming fragments report cumulative usage, so the last fragment is final).
364	func mergeAssistantEntries(a, b parsedEntry) parsedEntry {
365		merged := a
366		merged.ts = b.ts
367		if b.inputTokens > 0 {
368			merged.inputTokens = b.inputTokens
369		}
370		if b.outputTokens > 0 {
371			merged.outputTokens = b.outputTokens
372		}
373	
374		var aBlocks, bBlocks []json.RawMessage
375		_ = json.Unmarshal(a.content, &aBlocks) //nolint:errcheck // best-effort merge
376		_ = json.Unmarshal(b.content, &bBlocks) //nolint:errcheck // best-effort merge
377		all := append(aBlocks, bBlocks...)      //nolint:gocritic // intentional append to new slice
378		if data, err := json.Marshal(all); err == nil {
379			merged.content = data
380		}
381	
382		return merged
383	}
384	
385	// inlineToolResults adds "result" fields to matching tool_use blocks in the
386	// assistant entry's content, using outputs from user tool_result entries.
387	func inlineToolResults(assistant, user parsedEntry) parsedEntry {
388		var blocks []map[string]json.RawMessage
389		if json.Unmarshal(assistant.content, &blocks) != nil || len(blocks) == 0 {
390			return assistant
391		}
392	
393		for _, tr := range user.toolResults {
394			// Find the tool_use block matching this tool_use_id.
395			idx := -1
396			for i := len(blocks) - 1; i >= 0; i-- {
397				if unquote(blocks[i]["type"]) == transcript.ContentTypeToolUse {
398					if tr.toolUseID == "" || unquote(blocks[i]["id"]) == tr.toolUseID {
399						idx = i
400						break
401					}
402				}
403			}
404			// No matching tool_use block: do not attach a result to unrelated content.
405			if idx == -1 {
406				continue
407			}
408	
409			blocks[idx]["result"] = buildToolResult(tr)
410		}
411	
412		if data, err := json.Marshal(blocks); err == nil {
413			assistant.content = data
414		}
415	
416		return assistant
417	}
418	
419	// buildToolResult constructs the compact result object for a tool_use block,
420	// including optional rich metadata (file, matchCount) when available.
421	func buildToolResult(tr toolResultEntry) json.RawMessage {
422		r := toolResultJSON{
423			Output:     tr.output,
424			Status:     "success",
425			MatchCount: tr.matchCount,
426		}
427		if tr.isError {
428			r.Status = toolResultStatusError
429		}
430		if tr.file != nil {
431			r.File = &toolResultFileJSON{
432				FilePath: tr.file.filePath,
433				NumLines: tr.file.numLines,
434			}
435		}
436		b, err := json.Marshal(r)
437		if err != nil {
438			return nil
439		}
440		return b
441	}
