460	// isEmptyContentArray returns true if raw is a JSON empty array (`[]`).
461	func isEmptyContentArray(raw json.RawMessage) bool {
462		var arr []json.RawMessage
463		return json.Unmarshal(raw, &arr) == nil && len(arr) == 0
464	}
