548	// parseMessage extracts and parses the "message" field from a JSONL transcript
549	// line. All JSONL agents nest content inside a "message" object.
550	func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
551		msgRaw, ok := raw["message"]
552		if !ok {
553			return nil
554		}
555		var msg map[string]json.RawMessage
556		if json.Unmarshal(msgRaw, &msg) == nil {
557			return msg
558		}
559		return nil
560	}
561	
562	// userContent holds the extracted parts of a user message content array.
563	type userContent struct {
564		text        string
565		images      []json.RawMessage
566		toolResults []toolResultEntry
567	}
568	
569	// extractUserContent separates user message content into text, images, and tool_result entries.
570	// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
571	func extractUserContent(contentRaw json.RawMessage) userContent {
572		var str string
573		if json.Unmarshal(contentRaw, &str) == nil {
574			return userContent{text: textutil.StripIDEContextTags(str)}
575		}
576	
577		var blocks []json.RawMessage
578		if json.Unmarshal(contentRaw, &blocks) != nil {
579			return userContent{}
580		}
581	
582		var uc userContent
583	
584		for _, blockRaw := range blocks {
585			var block map[string]json.RawMessage
586			if json.Unmarshal(blockRaw, &block) != nil {
587				continue
588			}
589			blockType := unquote(block["type"])
590	
591			switch blockType {
592			case "tool_result":
593				var isErr bool
594				if raw, ok := block["is_error"]; ok {
595					_ = json.Unmarshal(raw, &isErr) //nolint:errcheck // best-effort
596				}
597				uc.toolResults = append(uc.toolResults, toolResultEntry{
598					toolUseID: unquote(block["tool_use_id"]),
599					output:    unquote(block["content"]),
600					isError:   isErr,
601				})
602	
603			case "image":
604				uc.images = append(uc.images, blockRaw)
605	
606			case transcript.ContentTypeText:
607				stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
608				if stripped != "" {
609					uc.text += stripped + "\n\n"
610				}
611			}
612		}
613	
614		uc.text = strings.TrimSpace(uc.text)
615		return uc
616	}
617	
618	func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
619		var str string
620		if json.Unmarshal(contentRaw, &str) == nil {
621			return contentRaw
622		}
623	
624		var blocks []map[string]json.RawMessage
625		if json.Unmarshal(contentRaw, &blocks) != nil {
626			return contentRaw
627		}
628	
629		result := make([]map[string]json.RawMessage, 0, len(blocks))
630		for _, block := range blocks {
631			blockType := unquote(block["type"])
632	
633			if blockType == "thinking" || blockType == "redacted_thinking" {
634				continue
635			}
636	
637			if blockType == transcript.ContentTypeToolUse {
638				stripped := make(map[string]json.RawMessage)
639				copyField(stripped, block, "type")
640				copyField(stripped, block, "id")
641				copyField(stripped, block, "name")
642				copyField(stripped, block, "input")
643				result = append(result, stripped)
644				continue
645			}
646	
647			result = append(result, block)
648		}
649	
650		b, err := json.Marshal(result)
651		if err != nil {
652			return contentRaw
653		}
654		return b
655	}
656	
657	// copyField copies a single key from src to dst if it exists.
658	func copyField(dst, src map[string]json.RawMessage, key string) {
659		if v, ok := src[key]; ok {
660			dst[key] = v
661		}
662	}
